frame_eqs_eel:
kick = max(bass - bass_att, 0);
pulse = max(pulse * 0.86, min(kick * 0.9, 1));
q3 = pulse;
pop = max(pop * 0.78, min(max(bass - 1.2, 0) * 0.55, 1.4));
q5 = pop;
rot = 0.006 * sin(time * 0.3) + 0.01 * q3;
zoom = 1.015 + 0.02 * q3;
wave_r = NOKKVI_HIGHLIGHT_R;
wave_g = NOKKVI_HIGHLIGHT_G;
wave_b = NOKKVI_HIGHLIGHT_B;

warp:
uniform sampler2D sampler_fc_cover;
 shader_body {
  vec2 s = texsize.xy / min(texsize.x, texsize.y);
  float box = 0.30 + 0.02 * clamp(bass_att, 0.0, 2.0) + 0.03 * q3 + 0.035 * q5;
  vec2 p = (uv_orig - 0.5) * s;
  float d = max(abs(p.x), abs(p.y));
  vec3 cov = texture(sampler_fc_cover, vec2(0.5, 0.5) + vec2(1.0, -1.0) * p / (2.0 * box)).xyz;
  float rim = (1.0 - step(box, d)) * smoothstep(box - 0.05, box, d);
  vec3 fb = texture(sampler_main, uv).xyz * 0.955 - 0.003;
  fb += cov * rim * (0.22 + 0.5 * q3 + 0.45 * q5);
  ret = max(fb, vec3(0.0));
 }

comp:
uniform sampler2D sampler_fc_cover;
 shader_body {
  vec2 s = texsize.xy / min(texsize.x, texsize.y);
  float box = 0.30 + 0.02 * clamp(bass_att, 0.0, 2.0) + 0.03 * q3 + 0.035 * q5;
  vec2 p = (uv - 0.5) * s;
  float d = max(abs(p.x), abs(p.y));
  vec3 fb = texture(sampler_main, uv).xyz + GetBlur1(uv) * 0.8;
  float lum = clamp(dot(fb, vec3(0.299, 0.587, 0.114)) * 1.3, 0.0, 1.0);
  float col_r_x = clamp(lum, 0.0, 1.0) * 5.0;
  vec3 col_r = mix(NOKKVI_RAMP0, NOKKVI_RAMP1, clamp(col_r_x, 0.0, 1.0));
  col_r = mix(col_r, NOKKVI_RAMP2, clamp(col_r_x - 1.0, 0.0, 1.0));
  col_r = mix(col_r, NOKKVI_RAMP3, clamp(col_r_x - 2.0, 0.0, 1.0));
  col_r = mix(col_r, NOKKVI_RAMP4, clamp(col_r_x - 3.0, 0.0, 1.0));
  col_r = mix(col_r, NOKKVI_RAMP5, clamp(col_r_x - 4.0, 0.0, 1.0));
  vec3 col = mix(NOKKVI_BG, col_r, smoothstep(0.02, 0.35, lum));
  col = mix(col, NOKKVI_TEXT, smoothstep(0.85, 1.0, lum) * 0.7);
  col += NOKKVI_WARM * smoothstep(0.75, 1.0, lum) * clamp(treb_att - 0.8, 0.0, 1.0) * 0.35;
  col *= 1.0 + 0.4 * q5;
  vec3 cov = texture(sampler_fc_cover, vec2(0.5, 0.5) + vec2(1.0, -1.0) * p / (2.0 * box)).xyz;
  float inside = 1.0 - smoothstep(box - 0.003, box, d);
  col = mix(col, cov, inside);
  float frame = smoothstep(0.010, 0.0, abs(d - box));
  col += NOKKVI_HIGHLIGHT * frame * (0.35 + 0.65 * max(q3, clamp(bass_att - 0.8, 0.0, 1.0)) + 0.9 * q5);
  ret = col;
 }
